 "en": "Responsiveness", "gender": "M", "mean": 20.54, "sd": 4.13}, {"key": "Do", "ar": "الانضباط", "en": "Dominance", "gender": "M", "mean": 15.39, "sd": 3.12}, {"key": "MAS", "ar": "مقياس القلق", "en": "Manifest anxiety", "gender": "M", "mean": 18.86, "sd": 7.45}, {"key": "A", "ar": "القلق العام", "en": "Anxiety", "gender": "M"}, {"key": "Pr", "ar": "الميل للجريمة", "en": "Prison", "gender": "M"}, {"key": "L", "ar": "الكذب", "en": "Lie", "gender": "F", "mean": 5.64, "sd": 2.48}, {"key": "F", "ar": "التزييف", "en": "Validity", "gender": "F", "mean": 11.69, "sd": 5.02}, {"key": "K", "ar": "التصحيح", "en": "Correction", "gender": "F", "mean": 12.25, "sd": 4.26}, {"key": "Hs", "ar": "توهم المرض", "en": "Hypochondriasis", "gender": "F", "mean": 16.35, "sd": 4.95, "correctionKey": "K", "correctionWeight": 0.5}, {"key": "D", "ar": "الاكتئاب", "en": "Depression", "gender": "F", "mean": 28.4, "sd": 5.04}, {"key": "Hy", "ar": "الهستيريا", "en": "Hysteria", "gender": "F", "mean": 22.82, "sd": 5.54}, {"key": "Pd", "ar": "الانحراف السيكوباثي", "en": "Psychopathic deviate", "gender": "F", "mean": 23.33, "sd": 4.44, "correctionKey": "K", "correctionWeight": 0.4}, {"key": "Mf", "ar": "الذكورة والأنوثة", "en": "Masculinity-femininity", "gender": "F", "mean": 31.83, "sd": 3.86}, {"key": "Pa", "ar": "البارانويا", "en": "Paranoia", "gender": "F", "mean": 12.62, "sd": 3.93}, {"key": "Pt", "ar": "القلق النفسي", "en": "Psychasthenia", "gender": "F", "mean": 31.17, "sd": 5.86, "correctionKey": "K", "correctionWeight": 1.0}, {"key": "Sc", "ar": "الفصام", "en": "Schizophrenia", "gender": "F", "mean": 34.89, "sd": 7.63, "correctionKey": "K", "correctionWeight": 1.0}, {"key": "Ma", "ar": "الهوس الخفيف", "en": "Hypomania", "gender": "F", "mean": 19.18, "sd": 4.89, "correctionKey": "K", "correctionWeight": 0.2}, {"key": "Si", "ar": "الانطواء الاجتماعي", "en": "Social introversion", "gender": "F", "mean": 37.27, "sd": 6.71}, {"key": "Q", "ar": "غير قابل للإجابة", "en": "Cannot answer", "gender": "F"}, {"key": "Es", "ar": "تقدير الذات", "en": "Ego strength", "gender": "F"}, {"key": "Cn", "ar": "النزاهة", "en": "Canonical", "gender": "F", "mean": 24.86, "sd": 3.7}, {"key": "Dy", "ar": "الاكتئاب الديناميكي", "en": "Dynamic depression", "gender": "F", "mean": 29.12, "sd": 7.61}, {"key": "St", "ar": "القلق البدني", "en": "Somatic tension", "gender": "F"}, {"key": "Re", "ar": "الانفعالية", "en": "Responsiveness", "gender": "F", "mean": 21.78, "sd": 3.13}, {"key": "Do", "ar": "الانضباط", "en": "Dominance", "gender": "F", "mean": 15.1, "sd": 2.76}, {"key": "MAS", "ar": "مقياس القلق", "en": "Manifest anxiety", "gender": "F", "mean": 20.43, "sd": 7.35}, {"key": "A", "ar": "القلق العام", "en": "Anxiety", "gender": "F"}, {"key": "Pr", "ar": "الميل للجريمة", "en": "Prison", "gender": "F"}, {"key": "clinicalMax", "ar": "أعلى ارتفاع سريري", "en": "Highest clinical elevation", "derive": "maxT", "sourceKeys": ["Hs", "D", "Hy", "Pd", "Pa", "Pt", "Sc", "Ma"], "hidden": true}, {"key": "clinicalMax", "hidden": true, "classify": true, "elevate": 65, "severityKey": "elevated", "severityAr": "ارتفاع سريري واضح", "severityEn": "Clinically significant elevation", "severityDescAr": "واحد أو أكثر من المقاييس السريرية الرئيسية فوق 65 درجة تائية وفق الجدول التقريبي المستخدم. يُقرأ في سياق مقاييس الصدق والأداء الإكلينيكي.", "severityDescEn": "One or more main clinical scales exceed T=65 on the approximate table used; interpret with validity scales and clinical context.", "tone": "amber"}, {"key": "clinicalMax", "hidden": true, "classify": true, "elevate": 75, "severityKey": "marked", "severityAr": "ارتفاع سريري شديد", "severityEn": "Marked clinical elevation", "severityDescAr": "واحد أو أكثر من المقاييس السريرية الرئيسية عند 75 درجة تائية أو أكثر. يتطلب تفسيراً متخصصاً ومراجعة مقاييس الصدق.", "severityDescEn": "One or more main clinical scales reach T=75 or above; specialist interpretation and validity review are required.", "tone": "rose"}]'::jsonb
  )
  on conflict (slug) do update set
    title_ar = excluded.title_ar,
    title_en = excluded.title_en,
    patient_label_ar = excluded.patient_label_ar,
    patient_label_en = excluded.patient_label_en,
    description_ar = excluded.description_ar,
    description_en = excluded.description_en,
    instructions_ar = excluded.instructions_ar,
    instructions_en = excluded.instructions_en,
    cutoffs = excluded.cutoffs,
    critical_rules = excluded.critical_rules,
    scale_meta = excluded.scale_meta,
    suite = 'clinical'
  returning id into v_id;

  delete from public.assessment_items where assessment_id = v_id;

  insert into public.assessment_items (
    assessment_id, position, domain_ar, domain_en, title_ar, title_en,
    text_ar, text_en, options, scales
  )
  select
    v_id,
    (item ->> 'position')::integer,
